import 'package:dio/dio.dart';
import '../../../core/networking/player_api_client.dart';
class PromotionItem { final String id,title,promotionType,status,startsAt,endsAt,claimStatus; const PromotionItem({required this.id,required this.title,required this.promotionType,required this.status,required this.startsAt,required this.endsAt,required this.claimStatus}); factory PromotionItem.fromJson(Map<String,dynamic> j)=>PromotionItem(id:j['id'] as String,title:j['title'] as String,promotionType:j['promotionType'] as String,status:j['status'] as String,startsAt:j['startsAt'] as String,endsAt:j['endsAt'] as String,claimStatus:j['claimStatus'] as String); }
class RewardCycleItem { final String id,cycleType,cycleKey,status; final String? expiresAt,claimedAt,rewardEventId; const RewardCycleItem({required this.id,required this.cycleType,required this.cycleKey,required this.status,this.expiresAt,this.claimedAt,this.rewardEventId}); factory RewardCycleItem.fromJson(Map<String,dynamic> j)=>RewardCycleItem(id:j['id'] as String,cycleType:j['cycleType'] as String,cycleKey:j['cycleKey'] as String,status:j['status'] as String,expiresAt:j['expiresAt'] as String?,claimedAt:j['claimedAt'] as String?,rewardEventId:j['rewardEventId'] as String?); }
class RewardsApi { final PlayerApiClient client; const RewardsApi(this.client); Future<List<PromotionItem>> promotions() async {final r=await client.get('/promotions');final b=Map<String,dynamic>.from(r.data as Map);if(b['ok']!=true)throw _err(r,'Promotions request failed');return (b['data'] as List).map((e)=>PromotionItem.fromJson(Map<String,dynamic>.from(e as Map))).toList();} Future<void> activatePromotion(String id) async{final r=await client.post('/promotions/$id/activate');_ok(r,'Promotion activation failed');} Future<void> openPromotion(String id) async{final r=await client.post('/promotions/$id/open');_ok(r,'Promotion open failed');} Future<List<RewardCycleItem>> cycles() async{final r=await client.get('/rewards/cycles');final b=Map<String,dynamic>.from(r.data as Map);if(b['ok']!=true)throw _err(r,'Rewards request failed');return (b['data'] as List).map((e)=>RewardCycleItem.fromJson(Map<String,dynamic>.from(e as Map))).toList();} Future<void> openCycle(String id) async{final r=await client.post('/rewards/cycles/$id/open');_ok(r,'Reward open failed');} DioException _err(Response r,String m)=>DioException(requestOptions:r.requestOptions,response:r,message:m);void _ok(Response r,String m){final b=Map<String,dynamic>.from(r.data as Map);if(b['ok']!=true)throw _err(r,m);} }
